import { useState } from 'react';
import { DsCheckbox } from '@primasoftllc/design-system';

export function BasicExample() {
  const [state, setState] = useState('checked');

  return (
    <DsCheckbox
      label="Отправка команд"
      description="Разрешить отправку команд выбранным объектам"
      state={state}
      onChange={setState}
    />
  );
}

partial-selection:
import { useState } from 'react';
import { DsCheckbox } from '@primasoftllc/design-system';

const labels = ['МАЗ 5440', 'Volvo FH16', 'Scania R450'];

export function PartialSelectionExample() {
  const [objects, setObjects] = useState([true, false, true]);
  const selected = objects.filter(Boolean).length;
  const groupState = selected === 0 ? 'unchecked'
    : selected === objects.length ? 'checked' : 'indeterminate';

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
      <DsCheckbox
        label="Все объекты группы"
        state={groupState}
        onChange={next => setObjects(current =>
          current.map(() => next === 'checked')
        )}
      />
      <div role="group" aria-label="Объекты группы"
        style={{ display: 'flex', flexDirection: 'column', gap: 8, paddingLeft: 28 }}>
        {labels.map((label, index) => (
          <DsCheckbox
            key={label}
            label={label}
            state={objects[index] ? 'checked' : 'unchecked'}
            onChange={next => setObjects(current =>
              current.map((value, i) => i === index ? next === 'checked' : value)
            )}
          />
        ))}
      </div>
    </div>
  );
}

