radio-selection:
import { useState } from 'react';
import { DsCheckbox } from '@primasoftllc/design-system';

export function RadioSelectionExample() {
  const [period, setPeriod] = useState('week');

  return (
    <div role="group" aria-label="Период"
      style={{ display: 'flex', flexWrap: 'wrap', gap: 16 }}>
      {['day', 'week'].map(value => (
        <DsCheckbox
          key={value}
          radio
          name="period"
          value={value}
          label={value === 'day' ? 'Сутки' : 'Неделя'}
          state={period === value ? 'checked' : 'unchecked'}
          onChange={() => setPeriod(value)}
        />
      ))}
    </div>
  );
}

