selection-states:
import { DsCheckbox } from '@primasoftllc/design-system';

const states = [
  ['unchecked', 'Чекбокс: не выбран', false],
  ['checked', 'Чекбокс: выбран', false],
  ['indeterminate', 'Чекбокс: частично', false],
  ['unchecked', 'Радио: не выбран', true],
  ['checked', 'Радио: выбран', true],
];

export function SelectionStatesExample() {
  return (
    <table aria-label="Состояния чекбокса и радио">
      <thead>
        <tr>
          <th scope="col">Состояние</th>
          <th scope="col">Обычное</th>
          <th scope="col">Недоступно</th>
        </tr>
      </thead>
      <tbody>
        {states.map(([state, label, radio], index) => (
          <tr key={label}>
            <th scope="row">{label}</th>
            {[false, true].map(disabled => (
              <td key={String(disabled)}>
                <DsCheckbox
                  state={state}
                  radio={radio}
                  disabled={disabled}
                  ariaLabel={label + (disabled ? ' — недоступно' : '')}
                  name={'sample-' + index + '-' + disabled}
                />
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}
